new = '''    // `1f` / `1b` are GAS local labels, not indirect targets.
    let is_label = |s: &str| {
        let named = s
            .chars()
            .all(|c| c.is_alphanumeric() || c == '_' || c == '.' || c == '$')
            && s.starts_with(|c: char| c.is_alphabetic() || c == '_');
        let numeric = s.len() >= 2
            && s[..s.len() - 1].chars().all(|c| c.is_ascii_digit())
            && (s.ends_with('f') || s.ends_with('b'));
        named || numeric
    };'''
